from pathlib import Path
import json,hashlib,sys,datetime
O=Path(__file__).parent;task=json.loads((O/'TASK.json').read_text());W=Path(task['source_worktree']);idx=int(sys.argv[1]);r=next(r for r in task['todo'] if r['id']==idx);history=json.loads((O/'PATCH-ATTEMPTS.json').read_text()) if (O/'PATCH-ATTEMPTS.json').exists() else []
if history and history[-1]['id']!=idx:assert history[-1].get('native_PASS'),('previous step unchecked',history[-1]['id'])
original=(O/r['block']).read_text();prior=next((x for x in reversed(history) if x['id']==idx),None);before=(O/prior['new_chunk_file']).read_text() if prior else original;after=(O/'new-chunks'/(str(idx)+'.lean.txt')).read_text();assert original.split(':=',1)[0]==after.split(':=',1)[0],'literal header changed';src=(W/r['path']).read_text();assert src.count(before)==1,(idx,'old chunk not literalonce');newsrc=src.replace(before,after);attempt=len(history)+1;out=O/'attempts'/f'{attempt:03d}-{idx}';out.mkdir(parents=True,exist_ok=True);(out/'before.lean.txt').write_text(before);(out/'after.lean.txt').write_text(after);(out/'owner-before.lean.txt').write_text(src);(out/'owner-after.lean.txt').write_text(newsrc);(W/r['path']).write_text(newsrc)
sha=lambda s:hashlib.sha256(s.encode()).hexdigest();row={'attempt':attempt,'id':idx,'name':r['name'],'path':r['path'],'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'original_chunk_file':r['block'],'old_chunk_file':str((out/'before.lean.txt').relative_to(O)),'new_chunk_file':str((out/'after.lean.txt').relative_to(O)),'source_before_sha256':sha(src),'source_after_sha256':sha(newsrc),'complete_header_literal_exact':True,'header':original.split(':=',1)[0],'old_chunk_sha256':sha(before),'new_chunk_sha256':sha(after),'native_PASS':False};history.append(row);(O/'PATCH-ATTEMPTS.json').write_text(json.dumps(history,indent=2)+'\n');print(json.dumps({'applied_id':idx,'attempt':attempt,'name':r['name'],'source_sha256':sha(newsrc)}),flush=True)
